-- ============================================================
--  Logistics ▸ Shipments (replaces the monday board "DostawyUK/Deliveries from PL" and Eledo).
--  A shipment to the UK: who imports it, the carrier / driver / plates, the invoices it carries
--  and its lines (quantity, unit, description, net / gross kg, comment = Z / order number). The
--  packing list (with or without photos, Polish / English) is generated by the office server.
--  Files — line photos, invoices, the CMR scan, the signed packing list and the CC599 export
--  confirmation — live in the private `shipments` storage bucket.
--  Access only via the office server (service-role key): RLS on, no policies.
-- ============================================================
create table if not exists shipments (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references tenants(id) on delete cascade,
  company          text not null default 'acemark' check (company in ('acemark', 'wem')),
  name             text not null,                    -- "UK PCW 06.11.2026"
  status           text not null default 'new' check (status in ('new', 'in_progress', 'sent', 'sent_no_docs')),
  ship_date        date,                             -- loading / shipment day
  deliver_by       date,                             -- "Przesyłkę należy dostarczyć dnia"
  invoices         text,                             -- "FL 7/ACE/11/2026 z dnia 06.11.2026" (one per line)
  importer         text,                             -- importer's name, address, VAT number
  customer_id      uuid,                             -- the customer card it was filled from (optional)
  delivery_address text,
  carrier          text,                             -- carrier's name and address
  carrier_id       uuid,
  driver           text,                             -- driver's full name and phone
  plates           text,                             -- licence plates (truck / trailer)
  seller           text,
  ship_from        text,
  notes            text,
  monday_item_id   text,                             -- imported from the monday board (history)
  created_by       uuid,
  created_by_name  text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  sent_at          timestamptz
);
create index if not exists shipments_tenant_idx on shipments(tenant_id, ship_date desc nulls first, created_at desc);
create unique index if not exists shipments_monday_idx on shipments(tenant_id, monday_item_id) where monday_item_id is not null;
alter table shipments enable row level security;

create table if not exists shipment_lines (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references tenants(id) on delete cascade,
  shipment_id  uuid not null references shipments(id) on delete cascade,
  pos          int not null default 0,
  qty          numeric,
  unit         text,                                 -- Szt. / kpl. / m2 …
  description  text not null default '',
  net_kg       numeric,
  gross_kg     numeric,
  comment      text,                                 -- "Z.437 - OK PL203104 - PCW - J034966P"
  loaded       boolean not null default false,       -- ticked on the phone while loading
  monday_item_id text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists shipment_lines_idx on shipment_lines(shipment_id, pos);
alter table shipment_lines enable row level security;

create table if not exists shipment_files (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references tenants(id) on delete cascade,
  shipment_id   uuid not null references shipments(id) on delete cascade,
  line_id       uuid references shipment_lines(id) on delete cascade,   -- a photo of one line
  kind          text not null default 'other' check (kind in ('photo', 'invoice', 'cmr', 'packing_signed', 'cc599', 'other')),
  storage_path  text not null,
  file_name     text,
  content_type  text,
  size          int,
  created_by_name text,
  created_at    timestamptz not null default now()
);
create index if not exists shipment_files_idx on shipment_files(shipment_id, kind);
alter table shipment_files enable row level security;

-- Carriers picked on a shipment; the driver and plates last used are remembered.
create table if not exists shipment_carriers (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id) on delete cascade,
  name        text not null,                         -- carrier's name and address (as printed)
  driver      text,
  plates      text,
  updated_at  timestamptz not null default now()
);
create unique index if not exists shipment_carriers_name_idx on shipment_carriers(tenant_id, name);
alter table shipment_carriers enable row level security;

insert into storage.buckets (id, name, public) values ('shipments', 'shipments', false)
  on conflict (id) do nothing;
